import XCTest
@testable import FlipTrainer

/// Asserts the Swift crypto against vectors generated by the Kotlin suite.
///
/// This is the only mechanism that catches a Swift/Kotlin divergence before it becomes "pairing
/// mysteriously fails on the device". If it goes red, one of the two implementations changed and
/// they no longer interoperate — fix the code, do not regenerate the vectors to match.
///
/// Regenerate deliberately, from the tested side:
/// ```
/// cd flip-trainer && ./gradlew :protocol:test -Dfliptrainer.updateGoldens=true
/// ```
final class PairingVectorTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Envelope: Decodable {
            let keyHex: String
            let direction: UInt8
            let counter: UInt64
            let payloadHex: String
            let macHex: String
        }

        let protocolVersion: Int
        let deviceId: String
        let pairingId: String
        let secretHex: String
        let clientNonceHex: String
        let serverNonceHex: String
        let clientProofHex: String
        let serverProofHex: String
        let pairedKeyHex: String
        let discriminatorHex: String
        let envelope: Envelope
    }

    private func loadVectors() throws -> Vectors {
        // ios-app/FlipTrainerTests -> ios-app -> flip-trainer -> test-fixtures
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("test-fixtures/pairing-vectors.json")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testProtocolVersionMatches() throws {
        XCTAssertEqual(try loadVectors().protocolVersion, ProtocolConstants.version)
    }

    func testClientProofMatchesKotlin() throws {
        let v = try loadVectors()
        let proof = PairingCrypto.clientProof(
            secret: Data(hexString: v.secretHex)!,
            deviceId: v.deviceId,
            pairingId: v.pairingId,
            clientNonce: Data(hexString: v.clientNonceHex)!,
            serverNonce: Data(hexString: v.serverNonceHex)!
        )
        XCTAssertEqual(proof.hexString, v.clientProofHex, "Swift and Kotlin client proofs diverged")
    }

    func testServerProofMatchesKotlin() throws {
        let v = try loadVectors()
        let proof = PairingCrypto.serverProof(
            secret: Data(hexString: v.secretHex)!,
            deviceId: v.deviceId,
            pairingId: v.pairingId,
            clientNonce: Data(hexString: v.clientNonceHex)!,
            serverNonce: Data(hexString: v.serverNonceHex)!
        )
        XCTAssertEqual(proof.hexString, v.serverProofHex, "Swift and Kotlin server proofs diverged")
    }

    func testDerivedPairedKeyMatchesKotlin() throws {
        let v = try loadVectors()
        let key = PairingCrypto.derivePairedKey(
            secret: Data(hexString: v.secretHex)!,
            deviceId: v.deviceId,
            pairingId: v.pairingId,
            clientNonce: Data(hexString: v.clientNonceHex)!,
            serverNonce: Data(hexString: v.serverNonceHex)!
        )
        XCTAssertEqual(key.hexString, v.pairedKeyHex, "HKDF output diverged — devices would derive different keys")
    }

    func testDiscriminatorMatchesKotlin() throws {
        let v = try loadVectors()
        XCTAssertEqual(PairingCrypto.discriminator(pairingId: v.pairingId).hexString, v.discriminatorHex)
    }

    func testEnvelopeMacMatchesKotlin() throws {
        let v = try loadVectors()
        let mac = PairingCrypto.envelopeMac(
            key: Data(hexString: v.envelope.keyHex)!,
            protocolVersion: v.protocolVersion,
            direction: v.envelope.direction,
            counter: v.envelope.counter,
            payload: Data(hexString: v.envelope.payloadHex)!
        )
        XCTAssertEqual(mac.hexString, v.envelope.macHex, "envelope MAC diverged — no message would authenticate")
    }

    func testHkdfMatchesRfc5869TestCase1() {
        let ikm = Data(repeating: 0x0b, count: 22)
        let salt = Data((0 ..< 13).map { UInt8($0) })
        let info = Data((0 ..< 10).map { UInt8(0xf0 + $0) })
        let okm = PairingCrypto.hkdf(inputKeyMaterial: ikm, salt: salt, info: info, length: 42)
        XCTAssertEqual(
            okm.hexString,
            "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865"
        )
    }
}

final class QrPairingPayloadTests: XCTestCase {
    func testRejectsMalformedCodes() {
        let bad = [
            "",
            "nonsense",
            "FT1:1:device:pairing",
            "XX1:1:device:pairing:AAAA:123",
            "FT1:notanumber:device:pairing:AAAA:123",
            "FT1:1:bad device:pairing:AAAA:123",
        ]
        for text in bad {
            XCTAssertThrowsError(try QrPairingPayload.decode(text), "should have rejected '\(text)'")
        }
    }

    func testRedactsSecretInDescription() throws {
        let secret = PairingCrypto.randomBytes(32)
        let payload = QrPairingPayload(
            protocolVersion: 1,
            deviceId: "flip5",
            pairingId: "abc",
            pairingSecret: secret,
            expiresAtEpochMs: 1
        )
        XCTAssertTrue(payload.debugDescription.contains("redacted"))
        XCTAssertFalse(payload.debugDescription.contains(secret.hexString))
    }

    func testExpiry() {
        let payload = QrPairingPayload(
            protocolVersion: 1,
            deviceId: "flip5",
            pairingId: "abc",
            pairingSecret: Data(repeating: 1, count: 32),
            expiresAtEpochMs: 1000
        )
        XCTAssertFalse(payload.isExpired(at: 999))
        XCTAssertTrue(payload.isExpired(at: 1000))
    }
}

final class SecureChannelTests: XCTestCase {
    private let key = Data(repeating: 0x2a, count: 32)

    func testRoundTrip() throws {
        let galaxy = SecureChannel(pairedKey: key, outboundDirection: .peripheralToCentral)
        let iphone = SecureChannel(pairedKey: key, outboundDirection: .centralToPeripheral)
        let payload = Data("rep 3".utf8)
        XCTAssertEqual(try iphone.open(try galaxy.seal(payload)), payload)
    }

    func testRejectsReplay() throws {
        let galaxy = SecureChannel(pairedKey: key, outboundDirection: .peripheralToCentral)
        let iphone = SecureChannel(pairedKey: key, outboundDirection: .centralToPeripheral)
        let envelope = try galaxy.seal(Data("x".utf8))
        _ = try iphone.open(envelope)
        XCTAssertThrowsError(try iphone.open(envelope))
    }

    func testRejectsTamperedPayload() throws {
        let galaxy = SecureChannel(pairedKey: key, outboundDirection: .peripheralToCentral)
        let iphone = SecureChannel(pairedKey: key, outboundDirection: .centralToPeripheral)
        let envelope = try galaxy.seal(Data("reps=10".utf8))
        let tampered = SealedEnvelope(
            protocolVersion: envelope.protocolVersion,
            direction: envelope.direction,
            counter: envelope.counter,
            payload: Data("reps=99".utf8),
            mac: envelope.mac
        )
        XCTAssertThrowsError(try iphone.open(tampered))
    }

    func testEnvelopeEncodingRoundTrips() throws {
        let galaxy = SecureChannel(pairedKey: key, outboundDirection: .peripheralToCentral)
        let envelope = try galaxy.seal(Data("hello".utf8))
        XCTAssertEqual(try SealedEnvelope.decode(envelope.encoded()), envelope)
    }

    func testFramingRoundTrips() throws {
        let message = Data((0 ..< 1000).map { UInt8($0 % 251) })
        let reassembler = Framing.Reassembler()
        var out: [Data] = []
        for chunk in Framing.chunk(message, chunkBytes: 60) {
            out.append(contentsOf: try reassembler.accept(chunk))
        }
        XCTAssertEqual(out.count, 1)
        XCTAssertEqual(out.first, message)
    }

    func testFramingRefusesAbsurdLength() {
        let hostile = Data([Framing.magic, 1, 0x7F, 0x7F, 0x7F, 0x7F])
        XCTAssertThrowsError(try Framing.Reassembler().accept(hostile))
    }
}
